import {fetchRideWeather} from './weather.js';
import {distance,orderedPoints,parseRoute,chooseRoutes,gpx} from './core.js';
const $=s=>document.querySelector(s);
const paths={bike:'<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-10 5 10H5l4-7h7l3 7M15 4h3M10 7H7"/>',locate:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',expand:'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',route:'<circle cx="6" cy="18" r="3"/><circle cx="18" cy="6" r="3"/><path d="M6 15V9a3 3 0 0 1 3-3h6m3 3v6a3 3 0 0 1-3 3H9"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.pin}</svg>`;}
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const state={start:{text:'',place:null},end:{text:'',place:null},stops:[{id:1,text:'',place:null}],nextId:2,location:null,routes:null,selected:'best',points:[],generation:0,phase:'planner'};
const map=L.map('map',{zoomControl:false}).setView([1.3521,103.8198],12);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
L.control.zoom({position:'bottomright'}).addTo(map);
const markers=L.layerGroup().addTo(map),lines=L.layerGroup().addTo(map);let locationMarker=null;
function status(message,busy=false){$('#status').textContent=message;$('#status').hidden=!message;$('#status').classList.toggle('busy',busy);}
function invalidate(){state.generation++;state.routes=null;lines.clearLayers();$('#legend').hidden=true;$('#map-caption').hidden=false;$('#map-caption').textContent='Your next great ride starts here.';status('');}
function escapeHtml(s){const e=document.createElement('span');e.textContent=s;return e.innerHTML;}
function makeField(model,type,index){const row=document.createElement('div');row.className='field-row';const id=type==='stop'?`stop-${model.id}`:type;row.innerHTML=`<div class="field-dot ${type}"></div><div class="field-body"><label for="${id}">${type==='start'?'Start':type==='end'?'Destination':`Stop ${index+1}`}</label><div class="input-wrap"><input id="${id}" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}-suggestions" placeholder="${type==='start'?'Choose starting location':type==='end'?'Where are you heading?':'Add a place along the way'}"><button class="clear" type="button" aria-label="Clear ${type}">×</button></div><div class="suggestions" role="listbox" id="${id}-suggestions" hidden></div></div>${type==='start'?`<button class="icon-button locate" type="button" aria-label="Use current location as start">${icon('locate')}</button>`:type==='stop'?'<div class="stop-actions"><button type="button" class="up" aria-label="Move stop up">↑</button><button type="button" class="remove" aria-label="Remove stop">×</button></div>':''}`;
 const input=row.querySelector('input'),suggestions=row.querySelector('.suggestions');input.value=model.text;let timer,controller,sequence=0;
 function close(){suggestions.hidden=true;input.setAttribute('aria-expanded','false');}
 function cancel(){sequence++;clearTimeout(timer);controller?.abort();close();}
 function pick(place){cancel();model.place=place;model.text=place.name;input.value=place.name;invalidate();updateMarkers();map.setView([place.lat,place.lon],14);input.focus();}
 input.addEventListener('input',()=>{model.text=input.value;model.place=null;invalidate();updateMarkers();cancel();if(input.value.trim().length<2)return;const request=sequence;timer=setTimeout(async()=>{suggestions.hidden=false;input.setAttribute('aria-expanded','true');suggestions.innerHTML='<div class="search-message">Finding nearby places…</div>';controller=new AbortController();try{const origin=state.location||state.start.place||{lat:map.getCenter().lat,lon:map.getCenter().lng};const query=new URLSearchParams({q:input.value.trim(),lat:origin.lat,lon:origin.lon,limit:12,lang:'en',location_bias_scale:0.1});const response=await fetch(`https://photon.komoot.io/api/?${query}`,{signal:controller.signal});if(!response.ok)throw Error('Search unavailable');const data=await response.json();if(request!==sequence||!row.isConnected)return;const seen=new Set();const places=data.features.map(f=>{const p=f.properties,c=f.geometry.coordinates;return {name:p.name||[p.street,p.housenumber].filter(Boolean).join(' ')||p.city||'Map location',address:[p.street,p.district,p.city,p.country].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(', '),lon:c[0],lat:c[1]};}).filter(p=>{const key=`${p.name}-${p.lat}-${p.lon}`;if(seen.has(key))return false;seen.add(key);return true;}).sort((a,b)=>distance(origin,a)-distance(origin,b)).slice(0,7);suggestions.replaceChildren();if(!places.length)suggestions.innerHTML='<div class="search-message">No matches. Try a street, park entrance, or postcode.</div>';for(const place of places){const b=document.createElement('button');b.type='button';b.className='suggestion';b.setAttribute('role','option');b.innerHTML=`${icon('pin')}<span><strong>${escapeHtml(place.name)}</strong><small>${escapeHtml(place.address)}</small></span><em>${distance(origin,place).toFixed(1)} km</em>`;b.onclick=()=>pick(place);suggestions.append(b);}}catch(e){if(e.name!=='AbortError'&&request===sequence)suggestions.innerHTML='<div class="search-message">Search is unavailable. Check your connection and try again.</div>'; }},450);});
 input.onkeydown=e=>{if(e.key==='Escape'){cancel();}if(e.key==='ArrowDown'){e.preventDefault();suggestions.querySelector('button')?.focus();}if(e.key==='Enter'&&!suggestions.hidden){e.preventDefault();suggestions.querySelector('button')?.click();}};
 suggestions.onkeydown=e=>{const buttons=[...suggestions.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();buttons[(i+1)%buttons.length]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();i<=0?input.focus():buttons[i-1].focus();}if(e.key==='Escape'){cancel();input.focus();}};
 row.addEventListener('focusout',()=>setTimeout(()=>{if(!row.contains(document.activeElement))cancel();},120));row.querySelector('.clear').onclick=()=>{input.value='';input.dispatchEvent(new Event('input'));input.focus();};row.querySelector('.locate')?.addEventListener('click',()=>locate(true));if(type==='stop'){row.querySelector('.up').disabled=index===0;row.querySelector('.up').onclick=()=>{[state.stops[index-1],state.stops[index]]=[state.stops[index],state.stops[index-1]];invalidate();renderStops();updateMarkers();};row.querySelector('.remove').onclick=()=>{cancel();state.stops.splice(index,1);invalidate();renderStops();updateMarkers();};}return row;}
function renderFields(){$('#fields').replaceChildren(makeField(state.start,'start'),makeField(state.end,'end'));renderStops();}
function renderStops(){$('#stops').replaceChildren(...state.stops.map((s,i)=>makeField(s,'stop',i)));}
$('#add-stop').onclick=()=>{state.stops.push({id:state.nextId++,text:'',place:null});renderStops();$('#stops').lastElementChild.querySelector('input').focus();};
function updateMarkers(){markers.clearLayers();const points=[state.start.place,...state.stops.map(s=>s.place),state.end.place];points.forEach((p,i)=>{if(!p)return;const kind=i===0?'start':i===points.length-1?'end':'stop';const marker=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'',html:`<div class="pin ${kind}"><span>${kind==='start'?'●':kind==='end'?'⚑':i}</span></div>`,iconSize:[30,30],iconAnchor:[15,30]})}).addTo(markers);const text=document.createElement('span');text.textContent=p.name;marker.bindTooltip(text,{direction:'top',offset:[0,-25]});});}
let locating=false;
function locate(setStart=false,quiet=false){if(locating)return;if(!navigator.geolocation){status('Location is not supported here. Search for your starting place.');return;}locating=true;if(!quiet)status('Finding your location…',true);navigator.geolocation.getCurrentPosition(p=>{locating=false;state.location={lat:p.coords.latitude,lon:p.coords.longitude};locationMarker?.remove();locationMarker=L.circleMarker([state.location.lat,state.location.lon],{radius:8,fillColor:'#2878ed',fillOpacity:1,color:'#fff',weight:3}).addTo(map);map.setView([state.location.lat,state.location.lon],14);if(setStart){state.start={text:'Current location',place:{...state.location,name:'Current location'}};invalidate();renderFields();updateMarkers();}status('');},e=>{locating=false;if(!quiet)status(e.code===1?'Location access is blocked. Allow it in your browser settings, or search for a starting place.':'Could not get your location. Enable location services or search for a starting place.');},{enableHighAccuracy:true,timeout:12000,maximumAge:60000});}
$('#locate-map').onclick=()=>locate();$('#fit-map').onclick=()=>fitMap();
function fitMap(){if(lines.getLayers().length){const bounds=L.featureGroup(lines.getLayers()).getBounds();map.fitBounds(bounds,{padding:[45,45],maxZoom:15});}else{const p=[state.start.place,...state.stops.map(s=>s.place),state.end.place].filter(Boolean);if(p.length)map.fitBounds(p.map(x=>[x.lat,x.lon]),{padding:[45,45],maxZoom:15});}}
function phase(name){state.phase=name;for(const id of ['planner','results','detail'])$('#'+id).hidden=id!==name;$('#title').textContent=name==='planner'?'Create a cycling route':name==='results'?'Find your kind of ride':`${state.selected==='best'?'Best':'Fastest'} Route`;$('#subtitle').textContent=name==='planner'?'A little planning. A great ride.':name==='results'?'Compare your options. Make it your own.':'All planned. Ready when you are.';}
function journey(){const root=$('#journey');root.replaceChildren();state.points.forEach((p,i)=>{const row=document.createElement('div');row.className='journey-line';row.innerHTML=`<i style="${i>0&&i<state.points.length-1?'background:var(--blue)':''}"></i><small>${i===0?'Start':i===state.points.length-1?'End':'Via'}</small><span>${escapeHtml(p.name)}</span>`;root.append(row);});}
function time(seconds){const mins=Math.max(1,Math.round(seconds/60));return mins>=60?`${Math.floor(mins/60)} h ${mins%60} m`:`${mins} min`;}
function stats(r){return `<div class="stats"><div class="stat"><strong>${(r.metres/1000).toFixed(1)} km</strong><small>Distance</small></div><div class="stat"><strong>${time(r.seconds)}</strong><small>Est. ride time</small></div><div class="stat"><strong>↗ ${Math.round(r.ascent)} m</strong><small>Elevation gain</small></div><div class="stat weather-cell">${weatherCell(r)}</div></div><div class="coverage">${icon('bike')} ${r.coverage===null?'Cycling-path coverage unavailable':`${Math.round(r.coverage)}% mapped cycling paths`}</div><p class="weather-note">${weatherNote(r)}</p>`;}
function weatherCell(r){
 if(!r.weather)return '<strong>Loading…</strong><small>Ride weather</small>';
 if(r.weather.error)return '<strong>Unavailable</strong><small>Ride weather · try finding routes again</small>';
 const w=r.weather;return `<strong>${w.condition.symbol} ${w.condition.label}</strong><small>${w.low===w.high?w.low:`${w.low}–${w.high}`}°C · up to ${w.rain}% precipitation chance</small>`;
}
function weatherNote(r){
 if(!r.weather||r.weather.error)return '';
 const w=r.weather,format=t=>new Date(t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
 return `Leaving ${format(w.departure)} · arriving ~${format(w.arrival)} (your local time). Forecast sampled at ${w.count} points along the ride; conditions may vary.`;
}
async function loadWeather(routes){
 const departure=Date.now();
 await Promise.all([...new Set(Object.values(routes))].map(async r=>{
  try{r.weather=await fetchRideWeather(r,departure);}catch{r.weather={error:true};}
  if(state.routes!==routes)return;
  for(const [i,kind] of ['best','fastest'].entries()){
   const card=$('#route-cards').children[i];
   if(card&&routes[kind]===r){card.querySelector('.weather-cell').innerHTML=weatherCell(r);card.querySelector('.weather-note').textContent=weatherNote(r);}
  }
  if(state.phase==='detail')$('#detail-stats').innerHTML=stats(routes[state.selected]);
 }));
}
function renderRoutes(){const root=$('#route-cards');root.replaceChildren();for(const kind of ['best','fastest']){const r=state.routes[kind],b=document.createElement('button');b.className='route-card'+(kind===state.selected?' selected':'');b.setAttribute('aria-pressed',String(kind===state.selected));b.innerHTML=`<div class="route-top"><div class="route-art">${icon(kind==='best'?'bike':'bolt')}</div><div><h3>${kind==='best'?'Best':'Fastest'}</h3><p>${kind==='best'?'More cycling paths. A gentler pace.':'Less time getting there. More time there.'}</p></div><span class="radio">${kind===state.selected?'✓':''}</span></div>${stats(r)}`;b.onclick=()=>{state.selected=kind;renderRoutes();drawRoutes();};root.append(b);}}
function drawRoutes(){lines.clearLayers();const other=state.selected==='best'?'fastest':'best';L.polyline(state.routes[other].coordinates.map(c=>[c[1],c[0]]),{color:'#7e8986',weight:4,dashArray:'6 8',opacity:.8}).addTo(lines);const selected=state.routes[state.selected].coordinates.map(c=>[c[1],c[0]]);L.polyline(selected,{color:'#fff',weight:9,opacity:.9}).addTo(lines);L.polyline(selected,{color:'#fa641c',weight:5,opacity:1}).addTo(lines);$('#legend').hidden=false;$('#map-caption').hidden=true;}
$('#planner').onsubmit=async e=>{e.preventDefault();let points;try{points=orderedPoints(state.start.place,state.stops,state.end.place);if(points.some((p,i)=>i&&distance(p,points[i-1])<.01))throw Error('Two consecutive stops are the same. Choose a different place or remove the duplicate.');}catch(e){status(e.message);return;}const generation=++state.generation;const button=$('#find');button.disabled=true;status('Finding cycling paths and comparing routes…',true);const coords=points.map(p=>`${p.lon},${p.lat}`).join('|'),candidates=[];let failures=0;
 try{for(const [profile,alternative] of [['trekking',0],['fastbike',0],['trekking',1]]){if(generation!==state.generation)return;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),45000);try{const query=new URLSearchParams({lonlats:coords,profile,alternativeidx:alternative,format:'geojson','timode':'0','profile:maxSpeed':'25','profile:bikerPower':'100','profile:allow_steps':'0','profile:allow_ferries':'0',...(profile==='trekking'?{'profile:stick_to_cycleroutes':'1'}:{})});const response=await fetch(`https://brouter.de/brouter?${query}`,{signal:controller.signal});if(!response.ok)throw Error('Route unavailable');const r=parseRoute(await response.json());if(!Number.isFinite(r.metres)||!Number.isFinite(r.seconds))throw Error('Incomplete route');candidates.push(r);}catch(e){failures++;}finally{clearTimeout(timeout);}}
 if(generation!==state.generation)return;state.routes=chooseRoutes(candidates);state.points=points;state.selected='best';journey();renderRoutes();drawRoutes();fitMap();phase('results');void loadWeather(state.routes);const same=JSON.stringify(state.routes.best.coordinates)===JSON.stringify(state.routes.fastest.coordinates);$('#method-note').textContent=`Compared ${candidates.length} cycling route${candidates.length===1?'':'s'}. Best ranks mapped cycling-path share; Fastest ranks estimated time. ${same?'Both choices follow the same route for these stops. ':''}${failures?'Some routing candidates were unavailable. ':''}Coverage depends on OpenStreetMap tags.`;status('');}catch(e){if(generation===state.generation)status(e.message||'Could not calculate a route. Try again or choose nearby entrances.');}finally{button.disabled=false;}};
$('#edit').onclick=()=>{phase('planner');status('');};$('#select').onclick=()=>{phase('detail');$('#detail-stats').innerHTML=stats(state.routes[state.selected]);$('#detail-stops').replaceChildren(...state.points.map(p=>{const li=document.createElement('li');li.textContent=p.name;return li;}));};$('#back-options').onclick=()=>phase('results');
$('#download').onclick=()=>{const name=`CycleRoute ${state.selected} - ${state.points[0].name} to ${state.points.at(-1).name}`,blob=new Blob([gpx(state.routes[state.selected],state.points,name)],{type:'application/gpx+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`cycleroute-${state.selected}.gpx`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status('GPX download started. Check your browser’s downloads.');};
$('#about').onclick=()=>$('#about-dialog').showModal();$('#close-about').onclick=()=>$('#about-dialog').close();renderFields();
// Ask for the initial map location; denial leaves a usable Singapore overview.
locate(false,true);
